#include <cstdio>
#include <cstdlib>
#include <limits>
#include "engine/gameplay/menu_cursor_transition.hpp"
#include "engine/gameplay/menu_pointer_geometry.hpp"
namespace {unsigned checks=0;void check(bool ok,const char* why){++checks;if(!ok){std::fprintf(stderr,"ring transition: %s\n",why);std::abort();}}bool same(const gf::MenuCursorPose& a,const gf::MenuCursorPose& b){return a.x==b.x&&a.y==b.y&&a.diameter==b.diameter&&a.phase==b.phase&&a.item==b.item;}}
int main(){using namespace gf;MenuCursorTransition a,b;check(a.step(100,350,-1,0,0,96,0)&&b.step(100,350,-1,0,0,96,0),"start at current free pointer, not arbitrary origin");check(a.pose().diameter==48&&a.pose().x==100&&a.pose().phase==MenuCursorPhase::Free,"visible free diameter policy");
    for(unsigned i=0;i<7;++i){check(a.step(390+f32(i),190,4,400,200,96,.02f)&&b.step(420-f32(i),220+f32(i),4,400,200,96,.02f),"approach native UI update");check(same(a.pose(),b.pose()),"all in-zone pointer movement ignored visually during expansion");check(a.pose().diameter>=48&&a.pose().diameter<=96&&a.pose().x>=100&&a.pose().x<=400,"bounded expansion/centre interpolation without overshoot");}
    check(a.step(440,240,4,400,200,96,.01f)&&a.pose().phase==MenuCursorPhase::Snapped&&a.pose().x==400&&a.pose().y==200&&a.pose().diameter==96,"arrives at normal item anchor/size");const auto snapped=a.pose();for(unsigned n=0;n<32;++n)check(a.step(350+f32(n),150+f32(n),4,400,200,96,.01f)&&same(a.pose(),snapped),"snapped ring ignores pointer motion until zone exit");
    check(a.step(40,420,-1,0,0,96,0)&&a.pose().phase==MenuCursorPhase::Shrinking&&a.pose().x==snapped.x&&a.pose().diameter==snapped.diameter,"departing starts at displayed ring with no jump");check(a.step(40,420,-1,0,0,96,.07f)&&a.pose().diameter<96&&a.pose().diameter>48&&a.pose().x<400&&a.pose().x>40,"shrinks and moves toward departure pointer");const auto mid=a.pose();check(a.step(390,190,4,400,200,96,0)&&a.pose().x==mid.x&&a.pose().y==mid.y&&a.pose().diameter==mid.diameter,"reenter can reverse mid-shrink without resetting visual pose");check(a.step(390,190,4,400,200,96,.14f)&&same(a.pose(),snapped),"reversed expansion reaches exact snap pose");check(a.step(40,420,-1,0,0,96,.07f)&&a.step(20,450,-1,0,0,96,.07f)&&a.pose().x==20&&a.pose().y==450&&a.pose().diameter==48&&a.pose().phase==MenuCursorPhase::Free,"shrink tracks changing departing destination, then free follows raw pointer");check(a.step(80,410,-1,0,0,96,0)&&a.pose().x==80&&a.pose().y==410,"steady free cursor has no interpolation lag");
    check(a.digital(500,150,96)&&a.pose().phase==MenuCursorPhase::Digital&&a.latched_item()==-1,"digital path seeds actual normal selector position");check(a.step(40,80,-1,0,0,96,0)&&a.pose().x==500&&a.pose().diameter==96&&a.step(40,80,-1,0,0,96,.14f)&&a.pose().x==40&&a.pose().diameter==48,"mouse regains control continuously from displayed digital ring");
    for(unsigned bad=0;bad<6;++bad){const auto before=a.pose();const f32 seconds=bad==0?-1:bad==1?std::numeric_limits<f32>::quiet_NaN():bad==2?2:0;check(!a.step(bad==3?-1:10,bad==4?480:10,bad==5?7:-1,0,0,96,seconds)&&same(a.pose(),before),"invalid animation input leaves prior pose unchanged");}
    MenuPointerGeometry geometry;std::vector<Vertex> triangle(3);triangle[0].x=100;triangle[0].y=100;triangle[1].x=200;triangle[1].y=100;triangle[2].x=100;triangle[2].y=200;for(auto& v:triangle)v.z=.5f;geometry.begin(640,480);check(geometry.append(triangle,3,false,false,false),"owned projected source footprint");geometry.finish(true);unsigned item=7;check(geometry.near(120,120,0,&item)&&item==3,"actual hit is zero-distance snap");check(geometry.near(94,120,6,&item)&&item==3,"distance to source edge inclusive");check(!geometry.near(93,120,6,&item)&&item==7,"outside source approach band");check(!geometry.near(195,195,16,&item),"not fitted item bounding-box proximity");check(geometry.near(90,120,24,&item,3)&&item==3&&!geometry.near(90,120,24,&item,2),"latched item filter preserves only its own release zone");check(!geometry.near(90,120,-1,&item)&&!geometry.near(90,120,129,&item)&&!geometry.near(90,120,10,nullptr),"invalid proximity requests refuse");geometry.clear();check(!geometry.near(120,120,16,&item)&&item==7,"no stale geometry snapping after clear");
    std::printf("fixed-stroke cursor motion/proximity policy: %u checks PASS\n",checks);return 0;
}
